// The chrome every page section shares: the heading, its intro line, and
// the hero's eyebrow and lead.
main section {
  padding: 3rem 0;
}

main h2 {
  margin: 0;
  font-size: 2rem;
}

.intro {
  margin: 0.5rem 0 1.75rem;
  color: var(--muted);

  a {
    color: var(--text);
  }
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--accent-warm);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.85rem;
}

.lead {
  max-width: 60ch;
  margin: 1.5rem 0 0;
  font-size: 1.15rem;
  line-height: 1.6;
  color: var(--muted);
}

a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--accent-warm);
  outline-offset: 3px;
}

// Reveal on scroll (RevealDirective): the class only arrives in the browser,
// so the prerendered page and crawlers see everything at once.
.reveal {
  opacity: 0;
  transform: translateY(1.25rem);
  transition:
    opacity 0.7s ease,
    transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
  transition-delay: var(--reveal-delay, 0s);

  &.reveal-in {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

@media print {
  body {
    background: #fff;
    color: #000;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

// The hero's numbers count up with a CSS animation of this property.
@property --num {
  syntax: '<integer>';
  initial-value: 0;
  inherits: true;
}

