/**
 * Every 30 minutes: fresh credentials for the TURN relay of online
 * matches into `relay/turn` (ADR 0020), valid an hour, so a failed run
 * leaves the last ones for the next. Off with `RELAY_ON`.
 */
export const refreshRelay = RELAY_ON
  ? onSchedule(
      {
        schedule: 'every 30 minutes',
        memory: '256MiB',
        timeoutSeconds: 60,
        maxInstances: 1,
        retryCount: 0,
        secrets: [CLOUDFLARE_TURN_KEY],
      },
      withSentry(async () => {
        const { expireAt } = await refreshRelayOf(
          db(),
          parseTurnKey(CLOUDFLARE_TURN_KEY.value()),
          fetch,
          Date.now()
        );
        logger.info('Relay refreshed', {
          expireAt: new Date(expireAt).toISOString(),
        });
      })
    )
  : undefined;

/**
 * The gallery's daily pick for the UTC day before (ADR 0011): at 23:40
 * UTC, once the boards stopped verifying that day (`openDays` keeps it
 * open until 23:00), so the ranked attempts they verified are candidates.
 * Deployed only with `FEATURE_BEST_ON`.
 */
export const featureBest = FEATURE_BEST_ON
