{
  "name": "portfolio-cdk",
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "application",
  "sourceRoot": "apps/portfolio-cdk/src",
  "tags": ["infra", "cdk"],
  "implicitDependencies": ["portfolio"],
  "namedInputs": {
    "default": ["{projectRoot}/**/*", "sharedGlobals", "cdkTsconfig"],
    "cdkTsconfig": ["{workspaceRoot}/tsconfig.cdk.json"]
  },
  "targets": {
    "deploy": {
      "dependsOn": ["^build"],
      "executor": "@wolsok/nx-aws-cdk-v2:deploy",
      "options": {
        "output": "{workspaceRoot}/dist/{projectRoot}",
        "require-approval": "never",
        "all": true
      }
    },
    "destroy": {
      "executor": "@wolsok/nx-aws-cdk-v2:destroy",
      "options": {
        "all": true
      }
    },
    "bootstrap": {
      "executor": "@wolsok/nx-aws-cdk-v2:bootstrap",
      "options": {}
    },
    "test": {
      "executor": "@nx/jest:jest",
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
      "options": {
        "jestConfig": "apps/portfolio-cdk/jest.config.ts",
        "passWithNoTests": true
      }
    }
  }
}
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "outDir": "../../dist/out-tsc",
    "types": ["node"]
  },
  "exclude": ["**/*.spec.ts", "**/*.test.ts"],
  "include": ["**/*.ts"]
}
{
  "extends": "../../tsconfig.cdk.json",
  "compilerOptions": {
    "outDir": "../../dist/out-tsc",
    "types": ["node"],
    "module": "NodeNext",
    "moduleResolution": "NodeNext"
  },
  "include": [],
  "files": [],
  "references": [
    {
      "path": "./tsconfig.app.json"
    },
    {
      "path": "./tsconfig.spec.json"
    }
  ]
}
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "outDir": "../../dist/out-tsc",
    "types": ["jest", "node"]
  },
  "include": [
    "jest.config.ts",
    "src/**/*.test.ts",
    "src/**/*.spec.ts",
    "src/**/*.d.ts"
  ]
}

