import { chromium } from '@playwright/test';
const out = process.argv[2];
const b = await chromium.launch();
const runs = [
  ['de-dark-fig', 'de-DE', 'dark', 1280, '/blog/bacteria-wars-turn-relay/', 2],
  ['en-light-top', 'en-GB', 'light', 1280, '/blog/bacteria-wars-turn-relay/', -1],
  ['home-teaser', 'en-GB', 'light', 1280, '/', -2],
  ['index-de-phone', 'de-DE', 'light', 360, '/blog/', -1],
];
for (const [name, locale, scheme, width, path, fig] of runs) {
  const ctx = await b.newContext({ viewport: { width, height: 860 }, locale, colorScheme: scheme });
  const p = await ctx.newPage();
  const errors = [];
  p.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  await p.goto('http://localhost:4321' + path, { waitUntil: 'networkidle' });
  await p.waitForTimeout(800);
  if (fig >= 0) { await p.locator('wolsok-blog-figure').nth(fig).scrollIntoViewIfNeeded(); await p.waitForTimeout(800); }
  if (fig === -2) { await p.locator('#blog').scrollIntoViewIfNeeded(); await p.waitForTimeout(1500); }
  const broken = await p.evaluate(() => [...document.images].filter((i) => i.complete && i.naturalWidth === 0).map((i) => i.src));
  const o = await p.evaluate(() => document.documentElement.scrollWidth - innerWidth);
  await p.screenshot({ path: `${out}/${name}.png` });
  console.log(name, 'overflow', o, 'broken', broken.join(','), 'errors', errors.join('|'));
  await ctx.close();
}
await b.close();
EOF
